-- product.sku 가 아직 없는 variant (02 미매칭 제품)
SELECT v.product_sku, v.variant_sku, v.variant_name
FROM variant_seed v
LEFT JOIN product p ON p.sku = v.product_sku
WHERE p.id IS NULL
ORDER BY v.product_sku, v.variant_sku;

INSERT INTO product_variant (
    product_id, sku, name, color, price, image_url, detail_url,
    representative, active, source_collected_at, created_at, updated_at
)
SELECT
    p.id,
    v.variant_sku,
    v.variant_name,
    v.color,
    v.price,
    v.image_url,
    v.detail_url,
    v.representative,
    v.active,
    v.source_collected_at,
    NOW(),
    NOW()
FROM variant_seed v
JOIN product p ON p.sku = v.product_sku
WHERE NOT EXISTS (
    SELECT 1 FROM product_variant existing WHERE existing.sku = v.variant_sku
);

SELECT COUNT(*) AS variant_row_count FROM product_variant;

COMMIT;
